"""Original parametric ball/paddle, product-anchored mass and explicit component inertias."""
from pathlib import Path
import math,json,numpy as np
from pxr import Usd,UsdGeom,UsdPhysics,Sdf,Gf
ROOT=Path(__file__).resolve().parent
p=ROOT/'assets/ball.usda';p.unlink(missing_ok=True);s=Usd.Stage.CreateNew(str(p));root=UsdGeom.Xform.Define(s,'/Ball');s.SetDefaultPrim(root.GetPrim());UsdGeom.SetStageMetersPerUnit(s,1.);UsdGeom.SetStageUpAxis(s,'Z');UsdPhysics.RigidBodyAPI.Apply(root.GetPrim()).CreateKinematicEnabledAttr(True);root.GetPrim().AddAppliedSchema('PhysxRigidBodyAPI');root.GetPrim().CreateAttribute('physxRigidBody:enableCCD',Sdf.ValueTypeNames.Bool).Set(False);mass=UsdPhysics.MassAPI.Apply(root.GetPrim());mass.CreateMassAttr(.0027);mass.CreateDiagonalInertiaAttr(Gf.Vec3f(7.2e-7));ball=UsdGeom.Sphere.Define(s,'/Ball/Shell');ball.CreateRadiusAttr(.02);ball.CreateDisplayColorAttr([(1.,.65,.02)]);UsdPhysics.CollisionAPI.Apply(ball.GetPrim());s.GetRootLayer().Save()
p=ROOT/'assets/paddle.usda';p.unlink(missing_ok=True);s=Usd.Stage.CreateNew(str(p));root=UsdGeom.Xform.Define(s,'/Paddle');s.SetDefaultPrim(root.GetPrim());UsdGeom.SetStageMetersPerUnit(s,1.);UsdGeom.SetStageUpAxis(s,'Z');UsdPhysics.RigidBodyAPI.Apply(root.GetPrim())
vwood=math.pi*.078**2*.007+.026*.026*.110;vrubber=2*math.pi*.077**2*.003;rho_rubber=(.17-380*vwood)/vrubber
parts=[]
for name,rad,h,z,x,rho,color in [('Blade',.078,.007,.13,0.,380,(.65,.44,.23)),('RubberFront',.077,.003,.13,.005,rho_rubber,(.8,.02,.025)),('RubberBack',.077,.003,.13,-.005,rho_rubber,(.04,.04,.04))]:
 q=UsdGeom.Cylinder.Define(s,'/Paddle/'+name);q.CreateAxisAttr('X');q.CreateRadiusAttr(rad);q.CreateHeightAttr(h);q.AddTranslateOp().Set((x,0,z));q.CreateDisplayColorAttr([color]);UsdPhysics.CollisionAPI.Apply(q.GetPrim());m=math.pi*rad*rad*h*rho;parts.append((name,m,np.array([x,0,z]),np.diag([.5*m*rad*rad,*([m*(3*rad*rad+h*h)/12]*2)])))
q=UsdGeom.Cube.Define(s,'/Paddle/Handle');q.CreateSizeAttr(1.);q.AddScaleOp().Set((.026,.026,.11));q.CreateDisplayColorAttr([(.52,.32,.15)]);UsdPhysics.CollisionAPI.Apply(q.GetPrim());m=.026*.026*.11*380;parts.append(('Handle',m,np.zeros(3),m/12*np.diag([.026**2+.11**2,.026**2+.11**2,2*.026**2])))
com=sum(m*p for n,m,p,I in parts)/.17;I=sum(I+m*(np.eye(3)*np.dot(p-com,p-com)-np.outer(p-com,p-com)) for n,m,p,I in parts);api=UsdPhysics.MassAPI.Apply(root.GetPrim());api.CreateMassAttr(.17);api.CreateCenterOfMassAttr(Gf.Vec3f(*com));api.CreateDiagonalInertiaAttr(Gf.Vec3f(*np.diag(I)));s.GetRootLayer().Save()
ledger=dict(paddle=dict(reference='STIGA Royal Carbon5-Star170g',url='https://www.stigasports.com/en/product/royal-carbon-5-star',mass_kg=.17,published_mass_note='Description170g; specification165+/-5g. Simulation takes upper end170g.',geometry_status='Own dimensioned round-blade approximation, not an exact reproduction of the branded carbon layup.',wood_density_estimate_kg_m3=380,rubber_effective_density_kg_m3=rho_rubber,parts=[dict(name=n,mass_kg=m,centre_m=p.tolist()) for n,m,p,J in parts],centre_of_mass_m=com.tolist(),inertia_kg_m2=I.tolist()),ball=dict(diameter_m=.04,mass_kg=.0027,inertia_kg_m2=[7.2e-7]*3,model='thin spherical shell; rigid native collision envelope'),board=dict(reference_url='https://sanweisport.com/en/product/accessories/others/rebounding-board/',reference_material='15mm MDF with optional table-tennis rubber',mdf_panel_size_m=[.015,.60,.30],assembly_envelope_m=[.017,.60,.30],mdf_density_estimate_kg_m3=700,mdf_mass_kg=.015*.6*.3*700,rubber_thickness_m=.002,rubber_density_estimate_kg_m3=1000,rubber_mass_kg=.6*.3*.002*1000,panel_total_mass_kg=.015*.6*.3*700+.6*.3*.002*1000,construction='Fixed clamped board, two160x40x30mm aluminum feet and twoM6 mechanical clamps. Published stand weight/dimensions are ambiguous, so no panel-mass claim is taken from them.'),fidelity=['Station geometry/base/camera calibration unchanged.','Paddle mass matches published product; geometry/wood/foam are a documented build approximation.','Board is a custom panel using documented commercial return-board construction, not a claimed dimension-exact SANWEI replica.','Restitution/friction are estimated simulation parameters, not measured product specifications.','No spin lift, air drag, shell/foam deformation or wear.'])
(ROOT/'physical_design.json').write_text(json.dumps(ledger,indent=2)+'\n');print('physical design ledger and native ball/paddle assets built')
